contract InvMutTest {
    C c;

    constructor() { c = new C(address(this)); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    receive() external payable {}

    function run(address recipient, uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(address(this).balance >= amount);
        require(recipient != address(0) && recipient != address(c));

        uint beforeBalanceC = address(c).balance;
        uint beforeBalanceR = recipient.balance;

        c.withdrawAll(recipient); if (__ESBMC_reverted()) return;

        uint afterBalanceC = address(c).balance;
        uint afterBalanceR = recipient.balance;

        assert(afterBalanceC == 0 && afterBalanceR == beforeBalanceR + beforeBalanceC);
    }
}

